// The runtime of the decompiled scripts (docs/READABLE-GAME.md, phase 2). The scripts in
// this folder are generated by tools/decompile-scripts.mjs from the original bytecode;
// each one is a generator that the scheduler (src/script/scheduler.mjs) drives.
//
// Values are 16-bit words (0 to FFFF); "true" is FFFF. A script calls a game function
// (a native) or starts another script by yielding the call; the scheduler runs it and
// resumes the script with the result. The game state the scripts read and write is
// reached by name through `state`.
import * as NAMES from '../data/wram.mjs';
import { BYTE_BITS, BYTE_MASK, BYTE_SIGN, WORD_MASK, WORD_SIGN } from '../constants/bits.mjs';

export const TRUE = WORD_MASK;

// The events a waiting task ends on (wait(events, frames) returns the met ones): the
// counter, the glove's actions on the object (the action menu), the end of its
// motion and animation, and its defeat (the count of its record falls to 0).
export const EVENT = Object.freeze({
  TIMER: 0x1,
  TALK: 0x2,
  ARRIVED: 0x4,
  ANIMATION_END: 0x8,
  PICK_UP: 0x10,
  BUY: 0x20,
  GIVE: 0x40,
  EXAMINE: 0x80,
  USE: 0x100,
  OPEN: 0x200,
  CLOSE: 0x400,
  DEFEATED: 0x800,
  TARGET: 0x2000,
  MOVE_TO: 0x4000,
});
export const NATIVE = 'native';
export const SCRIPT = 'script';

// A word: the value wrapped to 16 bits.
export const word = (value) => value & WORD_MASK;
// A byte as a signed word (80 to FF become FF80 to FFFF).
export const signed = (byte) => (byte & BYTE_SIGN ? (WORD_MASK ^ BYTE_MASK) | byte : byte);
// A condition as a word.
export const truth = (condition) => (condition ? TRUE : 0);
const negative = (value) => (value & WORD_SIGN) !== 0;
// right - 1, as the original's DEC before CMP (0 becomes FFFF).
const below = (right) => (right - 1) & WORD_MASK;

// The original's comparisons. Several gate on the sign of one
// operand first and some compare against right - 1; they keep those quirks.
// left < right, and always true for right 0.
export const less = (l, r) => below(r) >= l;
// less, but a negative left is always less.
export const lessSignedLeft = (l, r) => negative(l) || below(r) >= l;
// less, but a negative right is never greater.
export const lessSignedRight = (l, r) => !negative(r) && below(r) >= l;
export const lessOrEqualSignedLeft = (l, r) => negative(l) || r >= l;
export const lessOrEqualSignedRight = (l, r) => !negative(r) && r >= l;
export const greaterSignedLeft = (l, r) => !negative(l) && r < l;
export const greaterSignedRight = (l, r) => negative(r) || r < l;
export const greaterOrEqualSignedLeft = (l, r) => !negative(l) && below(r) < l;
export const greaterOrEqualSignedRight = (l, r) => negative(r) || below(r) < l;
export const notEqualSignedLeft = (l, r) => !negative(l) && r !== l;
export const rightNotNegative = (l, r) => !negative(r);
export const notEqualOrNegativeLeft = (l, r) => negative(l) || r !== l;
export const notEqualOrNegativeRight = (l, r) => negative(r) || r !== l;

// The original multiplies with three 8x8 products of the hardware unit; the third takes the
// right factor's high byte twice, so the result is ll*rl + ((ll*rh + lh*rh) << 8).
export function multiply(left, right) {
  const leftLow = left & BYTE_MASK,
    leftHigh = left >>> BYTE_BITS,
    rightLow = right & BYTE_MASK,
    rightHigh = right >>> BYTE_BITS;
  return (
    (leftLow * rightLow + ((leftLow * rightHigh + leftHigh * rightHigh) << BYTE_BITS)) & WORD_MASK
  );
}
// Multiply the magnitudes; negate when exactly one signed factor was negative.
function signedProduct(left, right, leftSigned, rightSigned) {
  const leftNegative = leftSigned && negative(left),
    rightNegative = rightSigned && negative(right);
  const product = multiply(
    leftNegative ? -left & WORD_MASK : left,
    rightNegative ? -right & WORD_MASK : right,
  );
  return leftNegative !== rightNegative ? -product & WORD_MASK : product;
}
export const multiplySignedLeft = (l, r) => signedProduct(l, r, true, false);
export const multiplySignedRight = (l, r) => signedProduct(l, r, false, true);
export const multiplySigned = (l, r) => signedProduct(l, r, true, true);
// Shifts of 16 or more give 0.
const SHIFT_LIMIT = 16;
export const shiftLeft = (l, r) => (r >= SHIFT_LIMIT ? 0 : (l << r) & WORD_MASK);
export const shiftRight = (l, r) => (r >= SHIFT_LIMIT ? 0 : l >>> r);

// A call of a game function: the scheduler runs native `id` with the arguments and
// resumes the script with its result (undefined when it has none).
export function* native(id, ...args) {
  return yield { kind: NATIVE, id, args };
}
// Start script `id` as a child task and wait for its result.
export function* script(id, ...args) {
  return yield { kind: SCRIPT, id, args };
}
// The end of the whole script from inside a local subroutine.
export class ScriptEnd {
  constructor(result) {
    this.result = result;
  }
}

// Byte-addressed locals, for the few scripts that read one local at two widths.
export const localByte = (locals, at) => locals[at];
export const localWord = (locals, at) => locals[at] | (locals[at + 1] << BYTE_BITS);
export function setLocalWord(locals, at, value) {
  locals[at] = value & BYTE_MASK;
  locals[at + 1] = value >>> BYTE_BITS;
}

// The game state by name (until phase 3 the names of src/data/wram.mjs, or a plain
// offset for state without a name).
const at = (name) => (typeof name === 'number' ? name : NAMES[name]);
export function scriptState(mem) {
  return {
    byte: (name, offset = 0) => mem.read8(NAMES.WRAM + at(name) + offset),
    word: (name, offset = 0) => mem.read16(NAMES.WRAM + at(name) + offset),
    setByte: (name, offset, value) => mem.write8(NAMES.WRAM + at(name) + offset, value & BYTE_MASK),
    setWord: (name, offset, value) =>
      mem.write16(NAMES.WRAM + at(name) + offset, value & WORD_MASK),
  };
}
